input.new_string:
const { trim, slugify } = require('../src/str');

test('trim', () => {
  assert.strictEqual(trim('  a  '), 'a');
});

test('slugify lowercases', () => {
  assert.strictEqual(slugify('Hello'), 'hello');
});

test('slugify trims surrounding whitespace', () => {
  assert.strictEqual(slugify('  hello  '), 'hello');
});

test('slugify collapses runs of non-alphanumerics into one dash', () => {
  assert.strictEqual(slugify('Hello,   World!! 123'), 'hello-world-123');
  assert.strictEqual(slugify('a___b--c  d'), 'a-b-c-d');
});

test('slugify strips leading and trailing dashes', () => {
  assert.strictEqual(slugify('--hello--'), 'hello');
  assert.strictEqual(slugify('!!!hello???'), 'hello');
});

test('slugify returns empty string when nothing alphanumeric remains', () => {
  assert.strictEqual(slugify(''), '');
  assert.strictEqual(slugify('   '), '');
  assert.strictEqual(slugify('---'), '');
  assert.strictEqual(slugify('!@#$'), '');
});

test('slugify keeps alphanumerics and drops non-ASCII letters', () => {
  assert.strictEqual(slugify('abc123'), 'abc123');
  assert.strictEqual(slugify('café'), 'caf');
});

